'use client'
import { cn, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import styles from './spinner.module.css'

export interface SpinnerProps extends HTMLAttributes<HTMLSpanElement> {
  size?: 'sm' | 'md' | 'lg'
  /**
   * Accessible label announced by screen readers
   *
   * @defaultValue `Loading`
   * @see the component manifest
   */
  label?: string
  /**
   * Alias of `label` — the same invisible accessible name under the catalog's own spelling.
   *
   * `ariaLabel` is what the catalog calls a name nothing paints, so it is the guess an agent
   * makes after reading one other component (2026-08-21 report item 1). This component
   * predates the convention and shipped `label`; both work and neither is deprecated.
   */
  ariaLabel?: string
}

export function Spinner({ size = 'md', label, ariaLabel, className, ...props }: SpinnerProps) {
  useSignals()
  const resolvedLabel = ariaLabel ?? label ?? t(builtin.spinner.label)
  return (
    <span
      role="status"
      aria-label={resolvedLabel}
      data-size={size}
      className={cn(styles['spinner'], className as string | undefined)}
      {...props}
    />
  )
}

@layer cascivo.component {
  .spinner {
    display: inline-block;
    box-sizing: border-box;
    border-style: solid;
    border-color: currentColor;
    border-block-start-color: transparent;
    border-radius: var(--cascivo-radius-full);
    animation: global(cascivo-spin) 0.6s linear infinite;

    &[data-size='sm'] {
      width: 1rem;
      height: 1rem;
      border-width: 2px;
    }

    &[data-size='md'] {
      width: 1.5rem;
      height: 1.5rem;
      border-width: 2px;
    }

    &[data-size='lg'] {
      width: 2rem;
      height: 2rem;
      border-width: 3px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .spinner {
      animation-duration: 1.5s;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Spinner',
  description: 'Indeterminate loading indicator',
  category: 'feedback',
  // Markup is fully server-rendered; the only client-side work is re-resolving the
  // default label when the i18n locale or catalog changes, which is why the source
  // calls useSignals() and carries 'use client'. Nothing is unreachable with JS off.
  clientJs: 'enhancement',
  states: [],
  variants: [],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description:
        'Alias of `label` — the same invisible accessible name under the catalog spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      default: 'Loading',
      description: 'Accessible label announced by screen readers',
    },
  ],
  tokens: ['--cascivo-radius-full'],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: false,
  },
  examples: [
    { title: 'Default', code: '<Spinner />' },
    { title: 'Large', code: '<Spinner size="lg" />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['loading', 'progress', 'feedback'],
  intent: {
    whenToUse: [
      'Indicating indeterminate work where duration and progress are unknown',
      'Loading a small region or inline control where a shape preview is unnecessary',
      'Showing busy state in buttons or compact UI',
    ],
    whenNotToUse: [
      'Progress with a known percentage — use ProgressBar or ProgressCircle',
      'Loading content with a known structure — use Skeleton',
    ],
    antiPatterns: [
      {
        bad: 'A full-page spinner for content whose layout is known',
        good: '<Skeleton> mirroring the content shape to reduce perceived wait and layout shift',
        why: 'Skeletons preview structure and feel faster; spinners are best for short, shapeless waits',
      },
    ],
    related: [
      {
        name: 'Skeleton',
        relationship: 'alternative',
        reason: 'Skeleton suits content with a known shape',
      },
      {
        name: 'ProgressBar',
        relationship: 'alternative',
        reason: 'ProgressBar suits determinate progress',
      },
    ],
    a11yRationale:
      'role="status" with an accessible label (default "Loading", i18n-driven) so assistive tech announces the busy state rather than leaving the spin silent',
    flexibility: [
      {
        area: 'size',
        level: 'flexible',
        note: 'sm/md/lg to fit inline vs standalone use',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Radius must resolve to --cascivo-radius-full',
      },
    ],
  },
}
